        obj = json.loads(raw)
    except (json.JSONDecodeError, UnicodeDecodeError) as exc:
        raise DataError(f"snapshot is not valid JSON: {exc}")
    if not isinstance(obj, dict):
        raise DataError("snapshot: top-level value must be an object")
