                raise DataError("snapshot: malformed posting")
            doc_id = p["id"]
            if doc_id not in known_docs:
                raise DataError(
                    f"snapshot: posting references unknown document {doc_id!r}")
            if previous_doc is not None and doc_id <= previous_doc:
                if doc_id == previous_doc:
